if(match&&Number.isSafeInteger(start)&&start>=1){
 const prefix='v2:'+match[1]+':';
 const items:T[]=[];
 let index=start;
 for(let pair=0;pair<30;pair++){
  if(!alive())throw Error('Cancelled public feed');
  const responses=await Promise.allSettled([read(prefix+index),read(prefix+(index+1))]);
  const first=responses[0];
  if(first.status==='rejected')throw first.reason;
  items.push(...verify(first.value));
  // If the first page is last, its cursor ends the read. No count inference.
  if(!first.value.nextCursor)return items;
  if(first.value.nextCursor!==prefix+(index+1))
    throw Error('Public feed cursor mismatch');
  const second=responses[1];
  if(second.status==='rejected')throw second.reason;
  items.push(...verify(second.value));
  if(!second.value.nextCursor)return items;
  if(second.value.nextCursor!==prefix+(index+2))
    throw Error('Public feed cursor mismatch');
  index+=2;
  await new Promise(resolve=>setTimeout(resolve,120));
 }
 throw Error('Public feed page bound reached');
}
// Legacy pages: cursor-linked sequential fallback; no speculative index.
